syntax:
template <typename T> class numeric_limits {
    public:
        static constexpr bool is_specialized = false;
        // other member functions and constants
};

// Specialization for a specific type:
template <> class numeric_limits<int> {
    public:
        static constexpr bool is_specialized = true;
        static constexpr int min() { return -2147483648; }
        static constexpr int max() { return 2147483647; }
        // other type-specific members
};

code_example:
#include <iostream>
#include <limits>

int main() {
    std::cout << "Is int specialized? " << std::numeric_limits<int>::is_specialized << '\n';
    std::cout << "Minimum int: " << std::numeric_limits<int>::min() << '\n';
    std::cout << "Maximum int: " << std::numeric_limits<int>::max() << '\n';
    return 0;
}
